{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Ibrutinib, the closest high-similarity analogue, shows high BBB penetration in humans with a CSF/plasma ratio of 28.7%, directly supporting meaningful CNS access for the query's shared acrylamide-piperidine and phenoxyphenyl BTK-inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In rats, ibrutinib/FK886 achieved a brain/plasma ratio of 0.87 at 5 minutes after IV dosing, demonstrating good and rapid brain penetration that transfers to the closely related query structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tirabrutinib, another very similar BTK inhibitor, showed an unbound brain-to-plasma ratio of 8.5% at Cmax in rats, confirming meaningful brain exposure despite incomplete unbound equilibrium.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Structurally related BTK inhibitors tolebrutinib, fenebrutinib, and evobrutinib were detected at pharmacologically relevant concentrations in non-human primate CSF, supporting class-level CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The active ibrutinib metabolite PCI-45227 crossed the blood-brain barrier with quantifiable CSF levels, providing additional transferable evidence that this scaffold family achieves meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of ibrutinib and tirabrutinib, both of which have direct experimental evidence of meaningful CNS exposure in humans and rodents (CSF/plasma ~29%, brain/plasma 0.87, Kp,uu 8.5%). Although the physicochemical prior is only moderate and some efflux liability may exist, the strong transferable in vivo evidence from highly similar molecules supports a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF measurement exists for the exact query molecule.",
    "The query's pyrimidinone heterocycle differs slightly from ibrutinib's pyrazolopyrimidine, and its specific transporter profile is not experimentally characterized.",
    "Human CNS exposure data are available only for close analogues, not for the query itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

